content.css:
.hnh-bsc {
  font-family: "Segoe UI", system-ui, sans-serif;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.hnh-bsc {
  --navy: #0A1E32;
  --navy-2: #002E5A;
  --blue-dk: #1478BE;
  --blue: #13ACE3;
  --sky: #32A4E5;
  --surface: #F4F7FB;
  --card: #FFFFFF;
  --line: #DCE5EF;
  --muted: #5B6B7D;
  --ink: #0A1E32;
  --good: #0E9F8E;
  --good-bg: #E3F6F3;
  --warn: #EF8B00;
  --warn-bg: #FFF2E0;
  --bad: #DB280A;
  --bad-bg: #FDE9E5;
  --nodata: #9AA7B5;
  --nodata-bg: #EEF2F6;
  --track: #E6EBF0;
  --tab-text: #C3CEDB;
  --slicer-border: #CBD3DC;
  --missed-bar: #F5B865;
  --row-hl: #E8F2FA;
  --good-tx: #08776B;
  --warn-tx: #A35F00;
  --bad-tx: #A81E06;
  --nodata-tx: #5B6B7D;
  --p1: #002E5A;
  --p2: #1478BE;
  --p3: #13ACE3;
  --p4: #6E8196;
  --hdr-1: #13ACE3;
  --hdr-2: #1478BE;
  --hdr-3: #0A1E32;
}
.hnh-bsc,
.hnh-bsc * {
  box-sizing: border-box;
}
.hnh-bsc {
  height: 100%;
  width: 100%;
  overflow: auto;
  display: flex;
  flex-direction: column;
  background: var(--surface);
}
.hnh-bsc .view {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.hnh-bsc .view > * {
  flex: 1;
  min-height: 0;
}
.hnh-bsc .empty {
  margin: auto;
  padding: 40px;
  font-size: 18px;
  color: var(--muted);
  text-align: center;
}
/* header band: the logo ribbon */
.band {
  height: 112px;
  flex: none;
  position: relative;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 0 40px;
  gap: 28px;
  background: linear-gradient(100deg, var(--hdr-1) 0%, var(--hdr-2) 46%, var(--hdr-3) 100%);
}
.band svg.ribbon {
  position: absolute;
  right: 0;
  top: 0;
  height: 112px;
  opacity: 0.16;
}
.band .mark {
  height: 56px;
  width: 56px;
  flex: none;
}
.band h1 {
  margin: 0;
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.band .sub {
  font-size: 15px;
  opacity: 0.88;
  margin-top: 2px;
}
.band .ctx {
  margin-left: auto;
  text-align: right;
  font-size: 14px;
  line-height: 1.5;
  position: relative;
}
.band .ctx b {
  font-size: 18px;
  display: block;
}
.band .ctx .period {
  display: block;
}
/* overview: the report's 1860 x 870 box (design x 1.5); the generator's page buttons sit over the four pillar cards.
   Below 1600 x 720 the visual scrolls instead of squeezing the cards. */
.ov {
  display: grid;
  grid-template-columns: 450px repeat(4, minmax(0, 1fr));
  grid-template-rows: 348px minmax(0, 1fr);
  gap: 24px;
  min-width: 1600px;
}
.hnh-bsc .view > .ov {
  min-height: 720px;
}
.ov-overall,
.ov-pillar,
.ov-trend,
.ov-attention {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.ov h2 {
  margin: 0;
  font-size: 21px;
  font-weight: 600;
  color: var(--ink);
  line-height: 1.2;
}
.ov-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex: none;
}
.ov-sub {
  font-size: 16.5px;
  color: var(--muted);
  font-weight: 400;
}
.ov .chip {
  font-size: 16.5px;
  padding: 4.5px 12px;
  gap: 9px;
  white-space: nowrap;
}
.ov-delta {
  font-size: 19.5px;
  font-weight: 600;
  white-space: nowrap;
}
.ov-delta.up {
  color: var(--good-tx);
}
.ov-delta.down {
  color: var(--bad-tx);
}
.ov-delta.flat {
  color: var(--muted);
}
.ov-overall {
  padding: 21px 27px;
  gap: 15px;
}
.ov-ringrow {
  display: flex;
  align-items: center;
  gap: 27px;
}
.ov-ringrow .ring {
  flex: none;
}
.ring-track {
  stroke: var(--track);
}
.ring-arc {
  stroke: var(--navy);
}
.ring-score {
  fill: var(--ink);
  font-weight: 600;
}
.ring-of {
  fill: var(--muted);
  font-weight: 400;
}
.ov-facts {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: flex-start;
  min-width: 0;
}
.ov-overall .chip {
  font-size: 18px;
}
.ov-target {
  font-size: 18px;
  color: var(--muted);
  font-weight: 400;
}
.ov-dist {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.ov-dist-bar {
  display: flex;
  height: 12px;
  border-radius: 6px;
  overflow: hidden;
  gap: 3px;
}
.ov-dist-bar i {
  display: block;
  height: 100%;
}
.ov-dist-bar i.good {
  background: var(--good);
}
.ov-dist-bar i.warn {
  background: var(--warn);
}
.ov-dist-bar i.bad {
  background: var(--bad);
}
.ov-dist-bar i.nodata {
  background: var(--nodata);
}
.ov-dist-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 21px;
  font-size: 18px;
  font-weight: 400;
}
.ov-dist-counts span,
.ov-n {
  display: inline-flex;
  align-items: center;
  gap: 7.5px;
  white-space: nowrap;
}
.ov-dist-counts b {
  font-weight: 600;
}
.ov-pillar {
  padding: 21px 24px;
  gap: 13.5px;
}
.ov-phead {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.ov-sq {
  width: 15px;
  height: 15px;
  border-radius: 4.5px;
  flex: none;
  margin-top: 6px;
}
.ov-pname {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.ov-phead h3 {
  margin: 0;
  font-size: 21px;
  font-weight: 600;
  line-height: 27px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ov-phead .ov-sub {
  line-height: 21px;
}
.ov-scorerow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px 15px;
}
.ov-score {
  font-size: 51px;
  font-weight: 600;
  line-height: 1;
}
.ov-bar {
  position: relative;
  height: 9px;
  border-radius: 4.5px;
  background: var(--track);
  flex: none;
}
.ov-bar i {
  display: block;
  height: 9px;
  border-radius: 4.5px;
}
.ov-bar b {
  position: absolute;
  top: -4.5px;
  width: 3px;
  height: 18px;
  margin-left: -1.5px;
  background: var(--navy);
}
.ov-spark {
  display: block;
  flex: none;
}
.ov-counts {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 18px;
  font-weight: 600;
}
.ov-counts .ov-delta {
  margin-left: auto;
  font-size: 18px;
}
.ov-drill {
  margin-top: auto;
  font-size: 18px;
  font-weight: 600;
}
.ov-row2 {
  grid-column: 1/-1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 630px;
  gap: 24px;
  min-height: 0;
}
.ov-row2.no-trend {
  grid-template-columns: minmax(0, 1fr);
}
.ov-trend {
  padding: 21px 24px;
  gap: 15px;
}
.ov-trend .ov-head {
  align-items: center;
  flex-wrap: wrap;
  row-gap: 6px;
}
.ov-legend {
  margin-left: auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 21px;
  font-size: 18px;
  font-weight: 400;
}
.ov-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7.5px;
  white-space: nowrap;
}
.ov-legend i {
  display: block;
  width: 18px;
  height: 4.5px;
  border-radius: 3px;
}
.ov-legend i.dash {
  height: 0;
  border-top: 3px dashed var(--muted);
  border-radius: 0;
}
.ov-chart {
  flex: 1;
  min-height: 0;
  position: relative;
}
.ov-chart svg.lc {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.lc-grid {
  stroke: var(--track);
}
.lc-target {
  stroke: var(--muted);
}
.lc-y,
.lc-month {
  fill: var(--muted);
  font-weight: 400;
}
.lc-name {
  fill: var(--ink);
  font-weight: 600;
}
.ov-attention {
  padding: 18px 24px;
  gap: 6px;
}
.ov-attention .ov-head {
  justify-content: flex-start;
  align-items: center;
  gap: 15px;
  height: 30px;
}
.ov-att-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}
.ov-att-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  height: 66px;
  flex: none;
  padding: 0 6px;
  border-bottom: 1px solid var(--nodata-bg);
  cursor: context-menu;
}
.ov-att-row:hover {
  background: var(--row-hl);
}
.ov-att-row:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: -3px;
}
.ov-att-l {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.ov-att-name {
  font-size: 19.5px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ov-att-pillar {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 16.5px;
  color: var(--muted);
  font-weight: 400;
}
.ov-att-pillar i {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  flex: none;
}
.ov-att-r {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}
.ov-att-actual {
  font-size: 24px;
  font-weight: 600;
  color: var(--bad);
  line-height: 1.1;
}
.ov-att-target {
  font-size: 16.5px;
  color: var(--muted);
  font-weight: 400;
  white-space: nowrap;
}
.ov-foot {
  margin: auto 0 0;
  font-size: 18px;
  line-height: 22px;
  color: var(--muted);
  font-weight: 400;
  flex: none;
}
.ov-none {
  margin: 12px 6px;
  font-size: 18px;
  color: var(--muted);
  font-weight: 400;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  padding: 4px 12px;
  font-size: 14px;
  font-weight: 600;
  width: max-content;
}
span.mark {
  display: inline-block;
  flex: none;
  width: 10.5px;
  height: 10.5px;
  background: currentColor;
}
span.mark.good {
  border-radius: 50%;
  background: var(--good);
}
span.mark.warn {
  width: 9px;
  height: 9px;
  transform: rotate(45deg);
  background: var(--warn);
}
span.mark.bad {
  border-radius: 1px;
  background: var(--bad);
}
span.mark.nodata {
  width: 10px;
  height: 3px;
  background: var(--nodata);
}
.hnh-bsc.hc span.mark {
  background: var(--hc-fg);
}
.chip.good {
  background: var(--good-bg);
  color: var(--good-tx);
}
.chip.warn {
  background: var(--warn-bg);
  color: var(--warn-tx);
}
.chip.bad {
  background: var(--bad-bg);
  color: var(--bad-tx);
}
.chip.nodata {
  background: var(--nodata-bg);
  color: var(--nodata-tx);
}
/* pillar board: the report's 1860 x 870 box (design x 1.5). The report puts its native "By hospital" chart and drill
   button over .bd-slot-chart and .bd-slot-button, so the strip, the gap and the panel sizes are a contract with the
   generator: chart at (1224, 549, 612, 219) and button at (1224, 786, 612, 60) inside this box. */
.bd {
  display: grid;
  grid-template-rows: 96px minmax(0, 1fr);
  gap: 21px;
  min-width: 1600px;
}
.hnh-bsc .view > .bd {
  min-height: 846px;
}
.bd-strip,
.bd-table {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  min-width: 0;
}
.bd-strip {
  height: 96px;
  display: flex;
  align-items: center;
  gap: 33px;
  padding: 0 27px;
  overflow: hidden;
}
.bd-title {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: none;
}
.bd-crumb {
  font-size: 18px;
  color: var(--muted);
  font-weight: 400;
  white-space: nowrap;
}
.bd-pname {
  display: flex;
  align-items: center;
  gap: 12px;
}
.bd-sq {
  width: 18px;
  height: 18px;
  border-radius: 4.5px;
  flex: none;
}
.bd-strip h1 {
  margin: 0;
  font-size: 30px;
  font-weight: 600;
  line-height: 1.1;
  white-space: nowrap;
}
.bd-rule {
  width: 1px;
  height: 54px;
  background: var(--line);
  flex: none;
}
.bd-fig {
  display: flex;
  flex-direction: column;
  gap: 4.5px;
  flex: none;
}
.bd-fig-l {
  font-size: 16.5px;
  color: var(--muted);
  font-weight: 400;
  white-space: nowrap;
}
.bd-fig-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.bd-pscore {
  font-size: 36px;
  font-weight: 600;
  line-height: 1;
}
.bd-strip .chip {
  font-size: 16.5px;
  padding: 3px 12px;
  gap: 9px;
  white-space: nowrap;
}
.bd-delta,
.bd-weight {
  font-size: 24px;
  font-weight: 600;
  line-height: 36px;
  white-space: nowrap;
}
.bd-delta.up {
  color: var(--good-tx);
}
.bd-delta.down {
  color: var(--bad-tx);
}
.bd-delta.flat {
  color: var(--muted);
}
.bd-counts {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 21px;
  font-weight: 400;
  line-height: 36px;
  white-space: nowrap;
}
.bd-counts span {
  display: inline-flex;
  align-items: center;
  gap: 7.5px;
}
.bd-counts b {
  font-weight: 600;
}
.bd-q {
  flex: 1;
  min-width: 0;
  margin: 0;
  font-size: 18px;
  line-height: 24px;
  color: var(--muted);
  font-weight: 400;
  text-align: right;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.bd-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 660px;
  gap: 24px;
  min-height: 0;
}
.bd-table {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 21px 24px;
  overflow: hidden;
  min-height: 0;
}
.bd-thead-row {
  display: flex;
  align-items: center;
  gap: 18px;
  flex: none;
}
.bd-table h2 {
  margin: 0;
  font-size: 21px;
  font-weight: 600;
  white-space: nowrap;
}
.bd-hint {
  font-size: 18px;
  color: var(--muted);
  font-weight: 400;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bd-picker {
  margin-left: auto;
  flex: none;
  max-width: 330px;
  height: 45px;
  padding: 0 12px;
  font: inherit;
  font-size: 18px;
  font-weight: 600;
  color: var(--ink);
  background: var(--card);
  border: 1px solid var(--slicer-border);
  border-radius: 9px;
  cursor: pointer;
}
.bd-picker:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 1px;
}
.bd-picker:disabled {
  cursor: default;
}
.bd-grid {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.bd-thead,
.bd-row {
  display: grid;
  grid-template-columns: 144px minmax(0, 1fr) 114px 114px 123px 78px 156px;
  gap: 12px;
  align-items: center;
  padding: 0 12px;
}
.bd-thead {
  flex: none;
  height: 42px;
  border-bottom: 1px solid var(--line);
  font-size: 16.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.bd-thead span:nth-child(n+3) {
  text-align: right;
}
.bd-thead span:last-child {
  text-align: center;
}
.bd-tbody {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-top: 3px;
}
.bd-row {
  height: 78px;
  flex: none;
  border-radius: 9px;
  cursor: context-menu;
}
.bd-row:hover {
  background: var(--surface);
}
.hnh-bsc .bd-row.selected {
  background: var(--row-hl);
  outline: none;
  box-shadow: inset 4.5px 0 0 var(--blue-dk);
}
/* the panel names the selected KPI: the other rows stay readable */
.hnh-bsc .bd-row.dimmed {
  opacity: 1;
}
.bd-row:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: -3px;
}
.bd-row .chip {
  font-size: 16.5px;
  padding: 4.5px 12px;
  gap: 9px;
  white-space: nowrap;
}
.c-kpi {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.bd-name {
  display: flex;
  align-items: center;
  min-width: 0;
  font-size: 19.5px;
  font-weight: 600;
  white-space: nowrap;
}
.bd-name-t {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bd-tag {
  flex: none;
  margin-left: 9px;
  padding: 0 7.5px;
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 15px;
  line-height: 1.4;
  font-weight: 600;
  color: var(--muted);
}
.bd-obj {
  font-size: 16.5px;
  color: var(--muted);
  font-weight: 400;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.c-actual,
.c-target,
.c-var,
.c-score {
  text-align: right;
  white-space: nowrap;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.c-actual {
  font-size: 24px;
  font-weight: 600;
}
.c-target {
  font-size: 19.5px;
  color: var(--muted);
  font-weight: 400;
}
.c-var,
.c-score {
  font-size: 19.5px;
  font-weight: 600;
}
.c-var.good {
  color: var(--good-tx);
}
.c-var.warn {
  color: var(--warn-tx);
}
.c-var.bad {
  color: var(--bad-tx);
}
.c-trend {
  display: flex;
  justify-content: center;
}
.c-trend .spark-line {
  stroke-width: 2.6;
}
.c-trend .spark-dot.good {
  fill: var(--good);
}
.c-trend .spark-dot.warn {
  fill: var(--warn);
}
.c-trend .spark-dot.bad {
  fill: var(--bad);
}
.c-trend .spark-dot.nodata {
  fill: var(--nodata);
}
.bd-none {
  margin: 12px;
  font-size: 18px;
  color: var(--muted);
  font-weight: 400;
}
/* the panel's edge is an inset shadow: a border would shift the native chart and button slots by its width */
.bd-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--card);
  border-radius: 12px;
  box-shadow: inset 0 0 0 1px var(--line);
  overflow: hidden;
}
.bd-panel-main {
  height: 432px;
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 15px;
  padding: 24px 27px 12px;
  overflow: hidden;
}
.bd-slot-chart {
  flex: none;
  height: 219px;
  margin: 0 24px;
}
.bd-slot-button {
  flex: none;
  height: 60px;
