  --p2: var(--hc-fg);
  --p3: var(--hc-fg);
  --p4: var(--hc-fg);
  --track: var(--hc-bg);
  --row-hl: var(--hc-bg);
  --good-tx: var(--hc-fg);
  --warn-tx: var(--hc-fg);
  --bad-tx: var(--hc-fg);
  --nodata-tx: var(--hc-fg);
  --missed-bar: var(--hc-bg);
}
.hnh-bsc.hc .band {
  background: var(--hc-bg);
  color: var(--hc-fg);
  border-bottom: 2px solid var(--hc-fg);
}
.hnh-bsc.hc .seg button[aria-pressed=true] {
  background: var(--hc-bg);
  color: var(--hc-fg);
  outline: 2px solid var(--hc-sel);
}
.hnh-bsc.hc .own-card[aria-pressed=true] {
  background: var(--hc-bg);
  box-shadow: inset 0 0 0 3px var(--hc-sel);
}
.hnh-bsc.hc .chip,
.hnh-bsc.hc .cmp td {
  color: var(--hc-fg);
  border: 1px solid var(--hc-fg);
}
/* SVG colours live here so high contrast can replace them */
.gauge-track {
  stroke: #E4EBF3;
}
.spark-target {
  stroke: #0A1E32;
}
.spark-line {
  stroke: var(--sky);
}
.spark-dot {
  fill: var(--sky);
}
.mark-shape {
  fill: url(#hnh-mk);
}
.mk-a {
  stop-color: #fff;
}
.mk-b {
  stop-color: #DDEFFA;
}
.ribbon-shape {
  fill: #fff;
}
.hnh-bsc.hc .gauge-track {
  stroke: var(--hc-bg);
  stroke-dasharray: none;
}
.hnh-bsc.hc .gauge {
  outline: 1px dashed var(--hc-fg);
}
.hnh-bsc.hc .spark-target {
  stroke: var(--hc-fg);
}
.hnh-bsc.hc .spark-line {
  stroke: var(--hc-sel);
}
.hnh-bsc.hc .spark-dot {
  fill: var(--hc-sel);
}
.hnh-bsc.hc .mark-shape,
.hnh-bsc.hc .ribbon-shape {
  fill: var(--hc-fg);
}
.hnh-bsc.hc .selected {
  outline-color: var(--hc-sel);
}
.hnh-bsc.hc .ring-track {
  stroke: var(--hc-fg);
  stroke-opacity: 0.35;
}
.hnh-bsc.hc .ring-arc {
  stroke: var(--hc-sel);
}
.hnh-bsc.hc .lc-grid {
  stroke: var(--hc-fg);
  stroke-opacity: 0.35;
}
.hnh-bsc.hc .lc-target {
  stroke: var(--hc-fg);
}
.hnh-bsc.hc .ov-bar {
  outline: 1px solid var(--hc-fg);
}
.hnh-bsc.hc .bd-bar.missed {
  fill: var(--hc-bg);
  stroke: var(--hc-fg);
  stroke-width: 2;
}
.hnh-bsc.hc .bd-tline {
  stroke: var(--hc-fg);
}
.hnh-bsc.hc .bd-key i.missed {
  background: var(--hc-bg);
  border: 2px solid var(--hc-fg);
}
.hnh-bsc.hc .bd-row.selected {
  outline: 3px solid var(--hc-sel);
  outline-offset: -3px;
}
.hnh-bsc.hc .dt-band {
  fill: var(--hc-bg);
}
.hnh-bsc.hc .dt-band.good {
  fill: var(--hc-fg);
  fill-opacity: 0.22;
}
.hnh-bsc.hc .dt-band.warn {
  fill: var(--hc-fg);
  fill-opacity: 0.1;
}
.hnh-bsc.hc .dt-grid {
  stroke: var(--hc-fg);
  stroke-opacity: 0.35;
}
.hnh-bsc.hc .dt-tline {
  stroke: var(--hc-fg);
}
.hnh-bsc.hc .dt-chip {
  border: 1px solid var(--hc-fg);
}
.hnh-bsc.hc .dt-key i.swatch.good {
  background: var(--hc-fg);
  opacity: 0.22;
}
.hnh-bsc.hc .dt-key i.swatch.warn {
  background: var(--hc-fg);
  opacity: 0.1;
}
/* branch series outside comparison mode: which hospital the page shows */
.hnh-bsc .hint {
  flex: none;
  padding: 6px 24px;
  font-size: 16.5px;
  color: var(--muted);
  background: var(--card);
  border-bottom: 1px solid var(--line);
}
.cmp td[data-key] {
  cursor: context-menu;
}
.cmp td[data-key]:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: -3px;
}
